46	// The proxy rejects an unknown/pruned resume cursor with INVALID_ARGUMENT,
47	// which the client surfaces as ValidationError — the only ValidationError the
48	// catch-up RPC produces (ENG-1566).
49	const isCursorRejectedIMessageError = (error: unknown): boolean =>
50	  error instanceof ValidationError;
51	
52	const streamLabel = (
53	  kind: "messages" | "polls" | "groups",
54	  phone: string
55	): string =>
56	  `imessage.${kind}:${phone === SHARED_PHONE ? phone : sanitizePhone(phone)}`;
57	
58	// The acting party's identity, without the `isFromMe` half. Split out because
59	// `message.read`'s `isFromMe` is undocumented and most plausibly describes the
60	// *underlying message* — ours, for a genuine receipt — so trusting it there
61	// would suppress every receipt worth surfacing. Vacuous in shared mode: the
62	// sentinel never matches a real address.
63	const isActorCurrentAccount = (
64	  actor: SingleServiceAddressInfo | undefined,
65	  phone: string
66	): boolean =>
67	  phone !== SHARED_PHONE &&
68	  actor?.address !== undefined &&
69	  actor.address === phone;
70	
71	const isEventFromCurrentAccount = (
72	  event: Pick<MessageEvent | PollEvent | GroupEvent, "actor" | "isFromMe">,
73	  phone: string
74	): boolean => event.isFromMe || isActorCurrentAccount(event.actor, phone);
