76	const streamLog = createLogger("spectrum.imessage.stream");
77	
78	// Mapping does RPC work (message/attachment rebuilds), so its errors split
79	// two ways. Client errors marked `retryable` are transient (network blip,
80	// gateway restart): rethrow so resumableOrderedStream refetches the event
81	// via catch-up and the message is delivered late rather than lost.
82	const isRetryableMappingError = (error: unknown): boolean =>
83	  typeof error === "object" &&
84	  error !== null &&
85	  (error as { retryable?: unknown }).retryable === true;
86	
87	// Everything else is deterministic (schema/shape throws, non-retryable
88	// client errors) and must not wedge the stream: retrying would refetch the
89	// same poison event forever and the cursor would never advance. Convert the
90	// throw into an empty skip item — the same shape the isFromMe skips use —
91	// so the cursor moves past the event.
92	const skipUnmappable = async <T>(
93	  label: string,
94	  cursor: string,
95	  map: () => Promise<ResumableStreamItem<T>>
96	): Promise<ResumableStreamItem<T>> => {
97	  try {
98	    return await map();
99	  } catch (error) {
100	    if (isRetryableMappingError(error)) {
101	      throw error;
102	    }
103	    streamLog.warn(
104	      "skipping unmappable imessage event",
105	      {
106	        "spectrum.imessage.stream": label,
107	        "spectrum.imessage.cursor": cursor,
108	        ...errorAttrs(error),
109	      },
110	      error instanceof Error ? error : undefined
111	    );
112	    return { cursor, id: `unmappable:${cursor}`, values: [] };
113	  }
114	};
