116	/**
117	 * Side effect fired when a non-self `message.received` event is converted.
118	 * Receives the `chatGuid` of the inbound message. Implementations must be
119	 * synchronous and never throw — typical use is fire-and-forget cache lookup
120	 * + background API call.
121	 */
122	type OnInboundMessage = (chatGuid: string) => void;
123	
124	const toMessageItem = async (
125	  client: AdvancedIMessage,
126	  event: MessageEvent,
127	  phone: string,
128	  cursor: string,
129	  onInbound?: OnInboundMessage
130	): Promise<ResumableStreamItem<IMessageMessage>> => {
131	  if (event.type === "message.received") {
132	    if (event.message.isFromMe) {
133	      return { cursor, id: event.message.guid, values: [] };
134	    }
135	
136	    const cache = getMessageCache(client);
137	    const values = await toInboundMessages(client, cache, event, phone);
138	
139	    // After conversion succeeds — an event skipUnmappable discards must not
140	    // trigger a contact-card share (and burn its 24h dedupe slot) for a
141	    // message that was never delivered.
142	    const inboundChatGuid = event.message.chatGuids?.[0];
143	    if (inboundChatGuid) {
144	      onInbound?.(inboundChatGuid);
145	    }
146	
147	    return { cursor, id: event.message.guid, values };
148	  }
149	
150	  if (event.type === "message.reactionAdded") {
151	    if (isEventFromCurrentAccount(event, phone)) {
152	      return {
153	        cursor,
154	        id: `${event.messageGuid}:reaction:${event.sequence}`,
155	        values: [],
156	      };
157	    }
158	
159	    const cache = getMessageCache(client);
160	    return {
161	      cursor,
162	      id: `${event.messageGuid}:reaction:${event.sequence}`,
163	      values: await toReactionMessages(client, cache, event, phone),
164	    };
165	  }
166	
167	  if (event.type === "message.read") {
168	    const id = readReceiptMessageId(event);
169	    // Logged before any filtering: if this never fires, the upstream stream is
170	    // not delivering `message.read` at all and nothing downstream can be at
171	    // fault. Every drop below logs its own reason.
172	    streamLog.debug("received a read event", {
173	      "spectrum.imessage.read.message_guid": event.messageGuid,
174	      "spectrum.imessage.read.sequence": event.sequence,
175	      "spectrum.imessage.read.chat_guid": event.chatGuid,
176	      "spectrum.imessage.read.actor": event.actor?.address
177	        ? sanitizePhone(event.actor.address)
178	        : "none",
179	      "spectrum.imessage.read.is_from_me": event.isFromMe,
180	      "spectrum.imessage.read.line": phone,
181	    });
182	    // No actor-based self-check here, unlike reactions. Verified against a
183	    // live line: on this arm `actor` is *our own* line's address even when the
184	    // peer is the one who read, so `isEventFromCurrentAccount` (or its actor
185	    // half) would suppress every genuine receipt. `isFromMe` is no better —
186	    // it came back `false` for a peer read, the opposite of the reaction arm.
187	    //
188	    // Self-suppression is instead carried entirely by `toReadReceiptMessages`,
189	    // which requires the resolved target to be one of *our* outbound messages.
190	    // That holds regardless of what `actor`/`isFromMe` mean: our own
191	    // `chats.markRead()` marks *their* inbound messages, so its echo resolves
192	    // to an inbound target and is dropped.
193	    const cache = getMessageCache(client);
194	    return {
195	      cursor,
196	      id,
197	      values: await toReadReceiptMessages(client, cache, event, phone),
198	    };
199	  }
200	
201	  // Consumed for the cursor but not surfaced (edits, unsends, sticker
202	  // placements, reaction removals). Logged so "the stream is alive but this
203	  // event type never arrives" is distinguishable from "the stream is dead".
204	  streamLog.debug("message event consumed without mapping", {
205	    "spectrum.imessage.event_type": event.type,
206	    "spectrum.imessage.sequence": event.sequence,
207	  });
208	
209	  return {
210	    cursor,
211	    id: `${event.type}:${"messageGuid" in event ? event.messageGuid : "unknown"}:${event.sequence}`,
212	    values: [],
213	  };
214	};
