269	type CatchUpCompleteEvent = Extract<CatchUpEvent, { type: "catchup.complete" }>;
270	type MessageCatchUpEvent = MessageEvent | CatchUpCompleteEvent;
271	type PollCatchUpEvent = PollEvent | CatchUpCompleteEvent;
272	type GroupCatchUpEvent = GroupEvent | CatchUpCompleteEvent;
273	
274	const isMessageEvent = (event: CatchUpEvent): event is MessageEvent =>
275	  event.type.startsWith("message.");
276	
277	const isPollEvent = (event: CatchUpEvent): event is PollEvent =>
278	  event.type === "poll.changed";
279	
280	const isGroupEvent = (event: CatchUpEvent): event is GroupEvent =>
281	  event.type === "group.changed";
