283	async function* catchUpEvents<T extends MessageEvent | PollEvent | GroupEvent>(
284	  client: AdvancedIMessage,
285	  cursor: string,
286	  isWanted: (event: CatchUpEvent) => event is T
287	): AsyncGenerator<T | CatchUpCompleteEvent> {
288	  const since = toResumeAfter(cursor);
289	  if (since === undefined) {
290	    return;
291	  }
292	
293	  for await (const event of client.events.catchUp(since)) {
294	    if (event.type === "catchup.complete") {
295	      yield event;
296	      return;
297	    }
298	    if (isWanted(event)) {
299	      yield event;
300	    }
301	  }
302	}
303	
304	const toResumeAfter = (cursor: string | undefined): number | undefined => {
305	  if (!cursor) {
306	    return;
307	  }
308	  const sequence = Number(cursor);
309	  return Number.isSafeInteger(sequence) && sequence >= 0 ? sequence : undefined;
310	};
311	
312	async function* afterCursor(
313	  stream: CloseableAsyncIterable<MessageEvent | PollEvent | GroupEvent>,
314	  cursor?: string
315	): AsyncGenerator<MessageEvent | PollEvent | GroupEvent> {
316	  const resumeAfter = toResumeAfter(cursor);
317	  try {
318	    for await (const event of stream) {
319	      if (resumeAfter !== undefined && event.sequence <= resumeAfter) {
320	        continue;
321	      }
322	      yield event;
323	    }
324	  } finally {
325	    await stream.close?.();
326	  }
327	}
