329	const withClose = <T extends MessageEvent | PollEvent | GroupEvent>(
330	  source: CloseableAsyncIterable<T>,
331	  cursor?: string
332	): CloseableAsyncIterable<T> =>
333	  Object.assign(afterCursor(source, cursor) as AsyncGenerator<T>, {
334	    close: async () => {
335	      await source.close?.();
336	    },
337	  });
