339	const messageStream = (
340	  client: AdvancedIMessage,
341	  phone: string,
342	  onInbound?: OnInboundMessage,
343	  recover?: () => Promise<void>
344	): ManagedStream<IMessageMessage> =>
345	  resumableOrderedStream<MessageEvent, MessageCatchUpEvent, IMessageMessage>({
346	    fetchMissed: (cursor) => catchUpEvents(client, cursor, isMessageEvent),
347	    isCursorRejectedError: isCursorRejectedIMessageError,
348	    label: streamLabel("messages", phone),
349	    recover,
350	    processLive: (event) =>
351	      skipUnmappable(
352	        streamLabel("messages", phone),
353	        String(event.sequence),
354	        () =>
355	          toMessageItem(client, event, phone, String(event.sequence), onInbound)
356	      ),
357	    processMissed: (event) =>
358	      event.type === "catchup.complete"
359	        ? Promise.resolve(toCatchUpCompleteItem(event))
360	        : skipUnmappable(
361	            streamLabel("messages", phone),
362	            String(event.sequence),
363	            () =>
364	              toMessageItem(
365	                client,
366	                event,
367	                phone,
368	                String(event.sequence),
369	                onInbound
370	              )
371	          ),
372	    subscribeLive: (cursor) =>
373	      withClose(client.messages.subscribeEvents(), cursor),
374	  });
