436	const clientStream = (
437	  client: AdvancedIMessage,
438	  pollCache: PollCache,
439	  phone: string,
440	  includeGroupEvents: boolean,
441	  onInbound?: OnInboundMessage,
442	  recover?: () => Promise<void>
443	): ManagedStream<IMessageMessage> => {
444	  const streams: ManagedStream<IMessageMessage>[] = [
445	    messageStream(client, phone, onInbound, recover),
446	    pollStream(client, pollCache, phone, recover),
447	  ];
448	
449	  if (includeGroupEvents) {
450	    streams.push(groupStream(client, phone, recover));
451	  }
452	
453	  return mergeStreams(streams);
454	};
