456	const shareWhenProfileSynced = (
457	  tracker: ContactShareTracker,
458	  gate: ProfileSyncGate,
459	  chatGuid: string
460	): void => {
461	  // The existing 24-hour Line + chat dedupe must run before the project-level
462	  // Cloud gate. Repeat inbound messages therefore stay entirely local.
463	  if (tracker.hasRecentlyShared(chatGuid)) {
464	    return;
465	  }
466	
467	  gate
468	    .isEnabled()
469	    .then((enabled) => {
470	      if (enabled) {
471	        // Multiple messages may have awaited the same coalesced gate refresh.
472	        // maybeShare sets its cache synchronously, so only the first continues
473	        // to the RPC.
474	        tracker.maybeShare(chatGuid);
475	      }
476	    })
477	    .catch((error: unknown) => {
478	      // ProfileSyncGate handles expected Cloud failures and returns false.
479	      // Keep this boundary defensive so a faulty gate can never break inbound
480	      // message processing or create an unhandled rejection.
481	      streamLog.warn(
482	        "profile sync gate failed; skipping automatic contact sharing",
483	        errorAttrs(error),
484	        error instanceof Error ? error : undefined
485	      );
486	    });
487	};
488	
489	const contactShareHandler = (
490	  tracker: ContactShareTracker,
491	  profileSyncGate?: ProfileSyncGate | undefined
492	): OnInboundMessage =>
493	  profileSyncGate
494	    ? (chatGuid) => shareWhenProfileSynced(tracker, profileSyncGate, chatGuid)
495	    : (chatGuid) => tracker.maybeShare(chatGuid);
496	
497	export const messages = (
498	  clients: RemoteClient[],
499	  projectConfig?: ProjectData | undefined,
500	  profileSyncGate?: ProfileSyncGate | undefined
501	): ManagedStream<IMessageMessage> => {
502	  const pollCache = getPollCache(clients);
503	  // Direct callers retain the initialization-snapshot behavior. Cloud-backed
504	  // Spectrum clients also provide a refreshable project-level gate, checked
505	  // only after the 24h per-Line/chat tracker says a share is eligible.
506	  const staticShareEnabled = projectConfig?.profile?.imessageSynced === true;
507	  // Cloud clients can re-mint a rejected token; explicit/static-token clients
508	  // return undefined (nothing to refresh). Shared across this client array's
509	  // streams so the message + poll loops coalesce onto one re-mint.
510	  const recover = getCloudRecover(clients);
511	  const includeGroupEvents = !isSharedMode(clients);
512	  return mergeStreams(
513	    clients.map((entry) => {
514	      const tracker =
515	        staticShareEnabled || profileSyncGate
516	          ? getContactShareTracker(entry.client)
517	          : undefined;
518	      return clientStream(
519	        entry.client,
520	        pollCache,
521	        entry.phone,
522	        includeGroupEvents,
523	        tracker ? contactShareHandler(tracker, profileSyncGate) : undefined,
524	        recover
525	      );
526	    })
527	  );
528	};
