1	import type { AdvancedIMessage } from "@photon-ai/advanced-imessage/grpc";
2	import { type RemoteClient, SHARED_PHONE } from "../types";
3	
4	export const isSharedMode = (clients: RemoteClient[]): boolean =>
5	  clients.length === 1 && clients[0]?.phone === SHARED_PHONE;
6	
7	export const availablePhones = (clients: RemoteClient[]): string[] =>
8	  clients.map((c) => c.phone);
9	
10	export const clientForPhone = (
11	  clients: RemoteClient[],
12	  phone: string
13	): AdvancedIMessage => {
14	  // Shared mode: a single client serves every conversation regardless of
15	  // the phone arg, since the SDK exposes no per-number routing in this mode.
16	  if (isSharedMode(clients)) {
17	    const entry = clients[0];
18	    if (!entry) {
19	      throw new Error("No iMessage clients configured");
20	    }
21	    return entry.client;
22	  }
23	  const entry = clients.find((c) => c.phone === phone);
24	  if (!entry) {
25	    const list = availablePhones(clients).join(", ") || "<none>";
26	    throw new Error(
27	      `No iMessage client serves phone ${phone}. Available: ${list}`
28	    );
29	  }
30	  return entry.client;
31	};
32	
33	export const randomPhone = (clients: RemoteClient[]): string => {
34	  if (clients.length === 0) {
35	    throw new Error("No iMessage phones configured for this account");
36	  }
37	  if (isSharedMode(clients)) {
38	    return SHARED_PHONE;
39	  }
40	  const entry = clients[Math.floor(Math.random() * clients.length)];
41	  if (!entry) {
42	    throw new Error("No iMessage phones configured for this account");
43	  }
44	  return entry.phone;
45	};
