10	// Floor between forced re-mints so a stream reconnect storm can't hammer the
11	// cloud token endpoint — well below any token TTL, just enough to coalesce the
12	// message + poll streams asking at nearly the same instant.
13	const FORCE_REFRESH_MIN_INTERVAL_MS = 5000;
14	
15	interface CloudAuth {
16	  dispose: () => void;
17	  forceRefresh: () => Promise<void>;
18	}
19	
20	const cloudAuthState = new WeakMap<RemoteClient[], CloudAuth>();
21	
22	const requirePhone = (data: DedicatedTokenData, instanceId: string): string => {
23	  const phone = data.numbers?.[instanceId];
24	  if (!phone) {
25	    throw new Error(`iMessage instance ${instanceId} has no phone assigned`);
26	  }
27	  return phone;
28	};
