30	export async function createCloudClients(
31	  projectId: string,
32	  projectSecret: string
33	): Promise<RemoteClient[]> {
34	  let tokenData = await cloud.issueImessageTokens(projectId, projectSecret);
35	  let lastRefreshAt = Date.now();
36	
37	  // The instanceId stays paired with each entry in this closure so renewal
38	  // can rewrite `entry.phone` in place without leaking instanceId onto the
39	  // public RemoteClient shape. Empty in shared mode.
40	  const records: { entry: RemoteClient; instanceId: string }[] = [];
41	
42	  const syncPhones = (data: DedicatedTokenData) => {
43	    for (const { entry, instanceId } of records) {
44	      entry.phone = requirePhone(data, instanceId);
45	    }
46	  };
47	
48	  const renewal = createTokenRenewal({
49	    expiresInSeconds: () => tokenData.expiresIn,
50	    name: "imessage",
51	    refresh: async () => {
52	      tokenData = await cloud.issueImessageTokens(projectId, projectSecret);
53	      lastRefreshAt = Date.now();
54	      if (tokenData.type === "dedicated") {
55	        syncPhones(tokenData);
56	      }
57	    },
58	  });
59	
60	  // Re-mint unconditionally — wired to the stream recover hook so a token the
61	  // server rejects after a restart (UNAUTHENTICATED / "Invalid credentials",
62	  // not yet near expiry) is replaced. The per-RPC token function then hands the
63	  // fresh token to the next reconnect without recreating the gRPC channel.
64	  const forceRefresh = async (): Promise<void> => {
65	    if (Date.now() - lastRefreshAt < FORCE_REFRESH_MIN_INTERVAL_MS) {
66	      return;
67	    }
